window.SUBJECTS = window.SUBJECTS || [];
window.SUBJECTS.push({"id":"eco","n":"Economy","tab":"Economy","w":"Static economy only: concepts, banking, planning and long-running schemes.","topics":[{"id":"basics","n":"Concepts and National Income","qs":[{"id":"q0003","q":"Which of the following Indian economists contributed to Human Development Index?","o":["Amartya Sen","Abhijit Banerjee","Amiya Kumar Bagchi","Avinash Dixit"],"a":0,"x":"The Human Development Index was built for UNDP in 1990 by Mahbub ul Haq, working with Amartya Sen, whose capability approach is its foundation.","e":"HDI combines three things: a long healthy life, knowledge (schooling) and a decent standard of living (income).","src":["ASO 18 Aug 2025 S1"]},{"id":"q0046","q":"______ are known as goods and services that are purchased by their ultimate user.","o":["Public goods","Production goods","Merit goods","Consumption goods"],"a":3,"x":"Consumption (final) goods are bought by the ultimate user for direct use, like food or a shirt. Goods used to make other goods are producer or capital goods.","e":"Flour bought by a household is a consumption good; the same flour bought by a bakery is an intermediate good.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0055","q":"The Cobb-Douglas Production Function is applied to the:","o":["whole of the manufacturing industry","Banking and Finance Industry","Insurance Industry","Tourism Industry"],"a":0,"x":"Cobb and Douglas first tested their production function on data for the whole US manufacturing industry (1899–1922).","e":"Form: Q = A·L^a·K^b, where L is labour and K is capital.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0059","q":"__________ is calculated by averaging the square of the poverty gap ratio.","o":["Hunger Index","Haq Index","Sen Index","Human Development Index"],"a":2,"x":"The Sen Index (Amartya Sen, 1976) combines how many people are poor, how far below the line they are, and inequality among the poor.","e":"Headcount ratio counts the poor; the poverty gap measures how far below the line they fall.","src":["ASO 18 Aug 2025 S2"],"k":"Strictly, averaging the squared poverty gap is the Foster–Greer–Thorbecke (P2) measure; DSSSB's key marks the Sen Index."},{"id":"q0093","q":"People who are always poor and the people who are usually poor but may sometimes have a little more money (example: casual workers) are grouped together as __________.","o":["churning poor","occasionally poor","chronic poor","transient poor"],"a":2,"x":"Chronic poor: people who are always poor, together with those usually poor who occasionally have a little more money, such as casual workers.","e":"Churning poor move in and out of poverty; occasionally poor are rich most of the time but may sometimes fall below the line.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0138","q":"______________ refer to the benefits a firm or an individual causes to another for which they are not paid.","o":["Negative internalities","Negative externalities","Positive externalities","Positive internalities"],"a":2,"x":"A positive externality is a benefit that spills over to others without payment, like a beekeeper's bees pollinating a neighbour's orchard.","e":"A negative externality is a cost imposed on others, such as factory smoke.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0163","q":"Which indicator is commonly used to measure educational attainment in a country?","o":["Infant mortality rate","Life expectancy","Gross Domestic Product","Literacy rate"],"a":3,"x":"Literacy rate is the standard indicator of educational attainment, and one of the inputs of the Human Development Index.","e":"Infant mortality and life expectancy measure health; GDP measures output.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0209","q":"Who among the following developed 'Sen Index'?","o":["Bimal Roy Sen","Amartya Sen","Bipasha Sen","Radhakamal Sen"],"a":1,"x":"Amartya Sen developed the Sen Index (1976), a poverty measure combining headcount, the depth of the poverty gap, and inequality among the poor.","e":"Sen won the Nobel Prize in Economics in 1998 and the Bharat Ratna in 1999.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0246","q":"Arrange the following Sustainable Development Goals (SDG) in ascending order of their SDG number. A. Equality of Education B. Clean Water and Sanitation C. Decent Work and Economic Growth D. Good Health and Well Being","o":["A-B-C-D","C-A-D-B","A-D-B-C","D-A-B-C"],"a":3,"x":"The goals in SDG number order: Good Health and Well-being (3), Quality Education (4), Clean Water and Sanitation (6), Decent Work and Economic Growth (8).","e":"There are 17 SDGs for 2015–2030; Goal 1 is No Poverty.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0247","q":"What is the concept of disposable income?","o":["Disposable Income = Personal Income + (Personal Income Tax − Fees − Fines)","Disposable Income = Net Domestic Product − Public Income","Disposable Income = Personal Income − (Personal Income Tax + Fees + Fines)","Disposable Income = Personal Income + (Personal Income Tax + Fees + Fines)"],"a":2,"x":"Disposable income = personal income minus direct taxes and other compulsory payments (such as fees and fines). It is what households can spend or save.","e":"If personal income is ₹10 lakh and taxes and fees total ₹1.5 lakh, disposable income is ₹8.5 lakh.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0255","q":"Which of the following is a major cause of poverty in India?","o":["High literacy rate","Declining population","Low birth rate","Low capital formation"],"a":3,"x":"Low capital formation — too little investment in machinery, infrastructure and skills — keeps productivity and incomes low, which causes poverty.","e":"High population growth and unemployment are also listed causes.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0282","q":"___________ unemployment is a characteristic feature of Indian agriculture.","o":["Structural","Disguised","Frictional","Educated"],"a":1,"x":"Disguised unemployment is typical of Indian farming: more people work on a plot than needed, so removing some would not lower output.","e":"If 8 family members work a farm that needs 5, the 3 extra are disguisedly unemployed.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0328","q":"Which of the following is the feature of the economic system of India?","o":["Goods and services are distributed among people based on their needs and ability to buy.","The Government provides essential goods and services that the market fails to provide.","Only public healthcare facilities are provided to citizens.","Production depends on market forces."],"a":1,"x":"India has a mixed economy: markets decide most production, but the government provides essential goods and services that markets fail to supply, such as public health, schooling and infrastructure.","e":"The 1956 Industrial Policy Resolution set the public–private mix.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0331","q":"The ______ is essentially an adjustment factor used to convert nominal GNP into real GNP.","o":["GDP deflator","GNP deflator","GNP inflator","GDP inflator"],"a":1,"x":"The GNP deflator converts nominal GNP to real GNP: GNP deflator = (Nominal GNP ÷ Real GNP) × 100.","e":"If nominal GNP is ₹120 and real GNP is ₹100, the deflator is 120 — prices rose 20%.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0335","q":"What is the relationship between marginal cost (MC) and average total cost (ATC) when ATC is decreasing?","o":["MC is lesser than ATC.","MC remains equal to ATC.","MC is greater than ATC.","MC will remain unaffected."],"a":0,"x":"When marginal cost is below average total cost, it pulls the average down; so while ATC is falling, MC is less than ATC. MC cuts ATC at ATC's lowest point.","e":"Cricket example: a score below your batting average pulls the average down.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0364","q":"How do economies of scale impact production costs?","o":["Economies of scale refer to the reduction in average total cost as production increases, resulting in increased per-unit costs.","Economies of scale occur when the average variable cost decreases with increased production, leading to lower overall production costs.","Economies of scale indicate a direct proportionality between the average fixed cost and production output.","Economies of scale have no influence on production costs."],"a":1,"x":"Economies of scale mean average cost falls as output grows, as fixed costs are spread over more units and bulk buying and specialisation cut per-unit costs.","e":"A car plant making 1 lakh cars a year has a lower cost per car than one making 1,000.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0366","q":"_____ is a quantitative process of change of scale and size of the economy which can be measured.","o":["Growth","Development","Evolution","Progress"],"a":0,"x":"Growth is a quantitative, measurable rise in output, such as GDP; development is a wider qualitative change including health, education and welfare.","e":"A country can grow without developing if the gains don't reach people.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0374","q":"Worker population ratio is defined as ________.","o":["the percentage of employed persons in the population that is available for work","the percentage of employed persons in the working-age population","the total working people in a country","the percentage of employed persons in a sector"],"a":1,"x":"The worker population ratio is the percentage of employed persons in the population; DSSSB's key frames it against the working-age population.","e":"If 40 of 100 working-age people have jobs, WPR = 40%.","src":["ASO 21 Aug 2025 S3"],"k":"The PLFS (India's labour survey) defines WPR against the whole population in the age group being measured."},{"id":"q0380","q":"At the point of tangency between the short run average total cost and the long run average total cost, the short run marginal cost is _________.","o":["greater than the long run marginal cost","equals the long run marginal cost","less than the long run marginal cost","is far above the long run marginal cost"],"a":1,"x":"Where the short-run average cost curve touches the long-run average cost curve, short-run marginal cost equals long-run marginal cost.","e":"The long-run average cost curve is the 'envelope' of short-run curves.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0405","q":"GDP estimated at current prices and at constant prices is called ____ and ____ respectively.","o":["Real GDP; Nominal GDP","Real GNP; Nominal GNP","Inflation-adjusted GDP; Constant GDP","Nominal GDP; Real GDP"],"a":3,"x":"GDP at current prices is nominal GDP; GDP at constant (base-year) prices is real GDP, which removes the effect of inflation.","e":"India's current base year for GDP is 2011-12.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0417","q":"What is the primary focus of Amartya Sen's 'Capability Approach'?","o":["Availability of resources","Control over production units","Distribution of income and wealth","Individual capabilities and freedoms"],"a":3,"x":"Amartya Sen's capability approach judges well-being by people's capabilities and freedoms — what they are actually able to do and be — not just income or resources.","e":"This idea underlies the Human Development Index and Sen's book 'Development as Freedom' (1999).","src":["ASO 22 Aug 2025 S1"]},{"id":"q0451","q":"Which of the following types of unemployment arises when the economy faces a recession or depression?","o":["Disguised unemployment","Cyclical unemployment","Frictional unemployment","Structural unemployment"],"a":1,"x":"Cyclical unemployment appears when demand falls in a recession or depression, and falls back when the economy recovers.","e":"Frictional: between jobs. Structural: skills don't match jobs. Disguised: more workers than needed.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0457","q":"Which of the following can cause a leftward shift in the supply curve of a given good?","o":["Decrease in the price of other goods","Technological degradation or complexity in technology","Advancement and improvement in technology used in production","Fall in taxes and cost of production"],"a":1,"x":"A leftward (backward) shift of supply happens when production gets harder or costlier: worse technology, higher input costs or higher taxes.","e":"Better technology or lower taxes shift supply to the right.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0526","q":"Which among the following components is added to the Gross Domestic Product to arrive at the Net National Product?","o":["Income from Abroad","Depreciation","Tax payments","Transfer payments"],"a":0,"x":"Net factor income from abroad is added to GDP to get GNP; depreciation is then subtracted to get NNP.","e":"NNP at factor cost is national income.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0565","q":"Which among the following identities is incorrect?","o":["GDP = C + I + G + X - M","NNP = GNP - Depreciation","GDP Deflator = Real GDP/Nominal GDP × 100","NNP = NDP + NFIA"],"a":2,"x":"The GDP deflator is Nominal GDP ÷ Real GDP × 100, not Real ÷ Nominal, so that identity is wrong. The others are correct.","e":"Nominal GDP ₹150, real ₹120 → deflator = 125.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0567","q":"Which among the following components should be deducted from Gross Domestic Product to get the Net Domestic Product?","o":["Depreciation","Transfer payments","Tax payments","Interest received"],"a":0,"x":"NDP = GDP − depreciation (consumption of fixed capital).","e":"GDP ₹100 crore, depreciation ₹10 crore → NDP ₹90 crore.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0689","q":"______________ = GDP (Gross Domestic Product) + NFIA (net factor income from abroad).","o":["Net Domestic Product","Net National Product","Net national expenditure","Gross National Product"],"a":3,"x":"GNP = GDP + NFIA (net factor income from abroad).","e":"If Indians earn more abroad than foreigners earn in India, NFIA is positive and GNP > GDP.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0728","q":"Law of diminishing marginal utility, means the first unit of consumption of a good yields ________________ than the second unit.","o":["more price","less price","more utility","less utility"],"a":2,"x":"By the law of diminishing marginal utility, each extra unit gives less satisfaction, so the first unit gives more utility than the second.","e":"The first glass of water when thirsty is worth more than the fourth.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1334","q":"Which of the following components is not taken into account while calculating national income by expenditure method?","o":["Household consumption","Investment expenditure","Purchase of shares and bonds","Government expenditure"],"a":2,"x":"The expenditure method adds up household consumption, investment, government spending and net exports. Buying shares and bonds is a transfer of ownership, not new production, so it is excluded.","e":"Also excluded: second-hand goods and transfer payments.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1339","q":"Complementary goods have a __________ cross price elasticity.","o":["positive","negative","zero","infinite"],"a":1,"x":"Complementary goods (used together) have a negative cross-price elasticity: if one's price rises, demand for the other falls.","e":"Car and petrol are complements; tea and coffee are substitutes (positive).","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q0918","q":"Which index does the Government of India use to assess the employment situation in the country?","o":["Worker Population Ratio (WPR)","Human Development Index (HDI)","Gini Coefficient","Consumer Price Index (CPI)"],"a":0,"x":"The worker population ratio (WPR), from the Periodic Labour Force Survey, is used to judge India's employment situation, along with the unemployment rate and labour force participation rate.","e":"HDI measures human development; the Gini coefficient measures inequality; CPI measures inflation.","src":["PRT 17 Feb 2026 S3"]},{"id":"q0989","q":"What does BPO commonly refer to?","o":["Business Process Outsourcing","Banking Process Order","Basic Product Outsourcing","Business Private Operations"],"a":0,"x":"BPO means Business Process Outsourcing: firms contract out work such as customer support, billing or data entry.","e":"Voice BPOs are call centres; non-voice BPOs handle back-office work.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1095","q":"Why is human capital important for economic growth?","o":["It drives innovation and productivity","It boosts food production","It reduces foreign aid","It increases population growth"],"a":0,"x":"Human capital — people's education, skills and health — drives innovation and productivity, which are the base of long-run growth.","e":"Spending on schools and hospitals is called investment in human capital.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1138","q":"A commodity becomes a final good when: (A) it passes out of the economic flow; (B) it becomes ready for the next process. Select the correct option.","o":["Both (A) and (B) are correct","Only (B) is correct","Both (A) and (B) are INCORRECT","Only (A) is correct"],"a":3,"x":"A final good has passed out of the production flow to its end user; it needs no further processing. A good 'ready for the next process' is intermediate. So only A is correct.","e":"Bread bought by a household is final; flour bought by a bakery is intermediate.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1177","q":"What were the recommended national poverty lines for rural and urban areas by the Tendulkar Committee for 2011-12?","o":["₹1,000 per capita per month for rural areas and ₹1,200 per capita per month for urban areas","₹816 per capita per month for rural areas and ₹1,000 per capita per month for urban areas","₹500 per capita per month for rural areas and ₹700 per capita per month for urban areas","₹700 per capita per month for rural areas and ₹800 per capita per month for urban areas"],"a":1,"x":"The Tendulkar methodology gave 2011-12 poverty lines of ₹816 per person per month in rural areas and ₹1,000 in urban areas (about ₹27 and ₹33 a day), putting poverty at 21.9%.","e":"The Rangarajan Committee (2014) later suggested ₹972 rural and ₹1,407 urban.","src":["PRT 31 Mar 2026 S1"]},{"id":"q1219","q":"Which of the following is a part of urban infrastructure?","o":["Cattle shed","Multi-storey parking","Grain storage on a farm","Ploughing tools"],"a":1,"x":"Multi-storey parking is urban infrastructure. A cattle shed, farm grain store and ploughing tools are rural or agricultural assets.","e":"Urban infrastructure also includes metro rail, sewerage and flyovers.","src":["PRT 31 Mar 2026 S3"]},{"id":"q1230","q":"What does a high HDI value usually indicate for a country?","o":["Limited access to health services and education","High income inequality and poverty","High levels of human development","Low life expectancy and educational attainment"],"a":2,"x":"A high HDI value (close to 1) means a high level of human development: long life expectancy, good schooling and decent income.","e":"UNDP groups countries as very high, high, medium or low HDI.","src":["PRT 31 Mar 2026 S3"]},{"id":"q1267","q":"When did the NITI Aayog launch the baseline edition of the Multidimensional Poverty Index for India?","o":["2022","2025","2023","2021"],"a":3,"x":"NITI Aayog released India's baseline National Multidimensional Poverty Index in 2021, based on NFHS-4 (2015–16) data.","e":"It measures health, education and standard of living with 12 indicators.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1280","q":"Structural unemployment is mainly caused by __________.","o":["Cyclical fall in demand","Seasonal variation","Skill mismatch","Voluntary quitting"],"a":2,"x":"Structural unemployment comes mainly from a skill mismatch: workers' skills don't fit the jobs available as the economy changes.","e":"A typist displaced by computers is structurally unemployed until retrained.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1401","q":"The formula for calculating Net National Product (NNP) is ______.","o":["GNP – Depreciation","GDP + Depreciation","GNP + Depreciation","GDP – Depreciation"],"a":0,"x":"NNP = GNP − depreciation.","e":"NNP at factor cost is national income.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1437","q":"As per the Handbook of Statistics on the Indian Economy, 2019-20, published by the RBI, which state has the highest GDP?","o":["Tamil Nadu","Maharashtra","Karnataka","Gujarat"],"a":1,"x":"Maharashtra has the largest state GDP (GSDP) in India, according to the RBI's Handbook of Statistics.","e":"Maharashtra's capital, Mumbai, is India's financial hub.","src":["TGT 25 Jun 2023 S2"]},{"id":"q1486","q":"If the general price level increases, the purchasing power of money:","o":["Increases","Doubles","Decreases","Stays the same"],"a":2,"x":"When the general price level rises (inflation), each rupee buys fewer goods, so money's purchasing power falls.","e":"At 10% inflation, ₹100 buys what about ₹91 bought a year earlier.","src":["TGT 29 Aug 2025"]},{"id":"q1496","q":"Which of the following statements are correct? 1. Workers that are engaged by someone or an enterprise and are paid their wages on a regular basis are called regular salaried employees. 2. Workers who own and operate an enterprise to earn their livelihood are called self- employed. 3. Construction workers are called casual wage labourers.","o":["Only 2 and 3","1, 2 and 3","Only 1 and 3","Only 1 and 2"],"a":1,"x":"All three are right: regular salaried employees get wages regularly; self-employed people own and run their own enterprise; construction workers are typically casual wage labourers.","e":"In India most workers are self-employed.","src":["TGT 29 Aug 2025"]},{"id":"q1505","q":"In the context of production theory, what does the term 'marginal rate of technical substitution' (MRTS) measure?","o":["The rate at which total cost increases as output expands","The rate at which marginal cost decreases with an increase in output","The rate at which a firm can substitute between two inputs while keeping output constant","The rate at which average variable cost varies with changes in fixed inputs"],"a":2,"x":"The marginal rate of technical substitution (MRTS) is how much of one input (say capital) a firm can give up for one more unit of another (labour) while keeping output the same.","e":"It is the slope of an isoquant.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1522","q":"The sum total of aggregate factor payments in an economy, the national income, is equal to the aggregate value of the output of final goods, the _____.","o":["net income","gross domestic product","equilibrium income","aggregate demand"],"a":1,"x":"National income equals total factor payments, which in turn equals the value of all final goods and services produced — the gross domestic product.","e":"The circular flow: output = income = expenditure.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1541","q":"In income distribution, what does the Lorenz curve measure?","o":["The degree of income inequality in a society","The total income generated in a country's economy","The concentration of wealth among the richest individuals","The share of income earned by different quintiles of the population"],"a":0,"x":"The Lorenz curve shows the degree of income inequality: the further it bows below the line of equality, the more unequal the society.","e":"The Gini coefficient is calculated from the Lorenz curve.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1550","q":"Which of the following states has a higher proportion of population which is multi- dimensionally poor?","o":["Kerala","Bihar","Gujarat","Maharashtra"],"a":1,"x":"Bihar has the highest share of multidimensionally poor people in NITI Aayog's Multidimensional Poverty Index; Kerala has the lowest.","e":"The MPI uses three dimensions: health, education and standard of living.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0775","q":"In NITI Aayog's SDG India Index, which pairs of category and index score are correctly matched? 1. Aspirant: 0–49  2. Performer: 50–64  3. Front Runner: 65–99  4. Achiever: 100","o":["Only 2","1, 2, 3 and 4","Only 1 and 3","Only 3 and 4"],"a":1,"x":"All four pairs are correct: in NITI Aayog's SDG India Index, Aspirant = 0–49, Performer = 50–64, Front Runner = 65–99, Achiever = 100.","e":"The SDG India Index was first released in 2018.","src":["PGT 25 Sep 2025"]},{"id":"q0797","q":"The consumption per unit of income is known as:","o":["marginal propensity to save (MPS)","marginal propensity to consume (MPC)","average propensity to save (APS)","average propensity to consume (APC)"],"a":3,"x":"Average propensity to consume (APC) = total consumption ÷ total income, the consumption per unit of income.","e":"Income ₹100, consumption ₹80 → APC = 0.8, APS = 0.2 (APC + APS = 1).","src":["PGT 11 Jul 2025 S1"]},{"id":"q0808","q":"What does GEM refer to in context of human development?","o":["Global Economic Measurement","Gender Equality Monitor","Gender Empowered Measurement","General Education Metric"],"a":2,"x":"GEM is the Gender Empowerment Measure, introduced by UNDP in 1995 to measure women's share in political and economic decision-making.","e":"It was replaced by the Gender Inequality Index (GII) in 2010.","src":["PGT 22 Sep 2025"]},{"id":"q0830","q":"Which sector is the backbone of the Indian economy?","o":["Agriculture","Services","Information Technology","Manufacturing"],"a":0,"x":"Agriculture is called the backbone of the Indian economy because it employs the largest share of workers (about 45%) and supports rural livelihoods.","e":"Services contribute the largest share of GDP.","src":["PGT 26 Sep 2025"]},{"id":"q0844","q":"Which of the following accurately describes 'fixed costs' in production?","o":["Costs that include both explicit and implicit expenses","Costs that remain constant regardless of the level of production output","Costs that fluctuate based on market conditions","Costs that vary with the level of production output"],"a":1,"x":"Fixed costs stay the same whatever the output: rent, salaries of permanent staff, insurance. Variable costs change with output.","e":"A factory's rent is fixed; the raw material it uses is variable.","src":["PGT 14 Jul 2025"]},{"id":"q0845","q":"Select the INCORRECT option. Social infrastructure improves human productivity and efficiency through facilities for:","o":["energy","education","housing","health"],"a":0,"x":"Social infrastructure means education, health and housing, which improve human productivity. Energy is economic infrastructure.","e":"Economic infrastructure: power, transport, communication, banking.","src":["PGT 14 Jul 2025"]}]},{"id":"money","n":"Money, Banking and the RBI","qs":[{"id":"q0016","q":"In which year were Regional Rural Banks set up in India?","o":["1972","1975","1974","1971"],"a":1,"x":"Regional Rural Banks were set up on 2 October 1975 on the advice of the Narasimham Working Group. Prathama Bank, Moradabad (UP), was the first.","e":"RRB share capital: Centre 50%, sponsor bank 35%, state government 15%.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0124","q":"Suppose a bank has ₹10,000 crore as deposits and the CRR is 15%. What amount should the bank maintain in the form of cash holdings with it?","o":["₹1,500 crore","₹9,900 crore","₹9,000 crore","₹8,500 crore"],"a":0,"x":"CRR is the share of deposits a bank must keep with the RBI as cash. 15% of ₹10,000 crore = ₹1,500 crore.","e":"SLR is different: that share is kept in liquid assets such as government securities.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0176","q":"How do you calculate the spread interest rate?","o":["Lending rate plus deposit rate","Lending rate minus deposit rate","Bank rate minus repo rate","Bank rate plus repo rate"],"a":1,"x":"Spread (net interest margin) = lending rate minus deposit rate; it is the bank's main source of profit.","e":"Lend at 10% and pay 6% on deposits: the spread is 4%.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0177","q":"Which of the following is a challenge faced by MFIs in India?","o":["High repayment rates of loans","Over-regulation by international financial bodies","Lack of interest from rural populations","Over-indebtedness of clients"],"a":3,"x":"Over-indebtedness is a major MFI problem: poor borrowers take several loans from different lenders and then cannot repay.","e":"The 2010 Andhra Pradesh microfinance crisis was driven by over-indebtedness.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0205","q":"What is a cheque?","o":["A type of digital currency","A written instruction to a bank to pay money","A loan agreement with a bank","A form of direct cash payment"],"a":1,"x":"A cheque is a written, signed order from an account holder telling the bank to pay a stated sum to a named person or the bearer.","e":"A demand draft is issued by the bank itself, so it cannot bounce.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0211","q":"What is the primary role of Self-Help Groups (SHGs) in rural development?","o":["They promote collective savings and access to microfinance.","They provide rural households with subsidised government loans.","They act as informal money lenders in villages.","They serve as rural government employment offices."],"a":0,"x":"Self-Help Groups, usually 10–20 rural women, pool small savings and give members loans, which helps them get microfinance and bank credit.","e":"NABARD's SHG–Bank Linkage Programme began in 1992.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0216","q":"Identify the correct statement(s) from the following in the context of Cash Reserve Ratio. i. Central banks adopt this method to control credit. ii. The first time it was adopted by the Federal Reserve System of the USA. iii. It does not apply to non-banking financial intermediaries.","o":["Only i","Only ii","Only i and iii","All, i, ii and iii"],"a":2,"x":"Statement i is true: CRR is a quantitative credit-control tool. Statement iii is true: CRR applies to banks, not NBFCs. DSSSB's key treats statement ii as false.","e":"Cutting CRR releases money for banks to lend; raising it pulls money out of the system.","src":["ASO 20 Aug 2025 S1"],"k":"Many Indian textbooks say the variable reserve ratio was first used by the US Federal Reserve (1930s), which would make ii true too. DSSSB's key marks 'only i and iii'."},{"id":"q0254","q":"Which institution(s) has/have the sole right to issue currency notes in India?","o":["Reserve Bank of India","Ministry of Finance","Stock exchanges","Commercial banks"],"a":0,"x":"The RBI has the sole right to issue banknotes in India under Section 22 of the RBI Act, 1934.","e":"The ₹1 note and all coins are issued by the Government of India (Ministry of Finance).","src":["ASO 20 Aug 2025 S2"]},{"id":"q0285","q":"Which of the following banks has the tagline ‘One Family One Bank’?","o":["Central Bank of India","Bank of India","Canara Bank","Bank of Maharashtra"],"a":3,"x":"'One Family One Bank' is the tagline of Bank of Maharashtra, headquartered in Pune.","e":"SBI: 'The Banker to Every Indian'.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0300","q":"What is the primary objective of Microfinance Institutions (MFIs) in India?","o":["Providing only insurance services","Investing in stock markets and mutual funds","Lending to large companies at high interest rates","Providing financial services to people who are underserved or excluded from banking"],"a":3,"x":"Microfinance institutions give small loans, savings and insurance to low-income people who are underserved or left out by banks.","e":"Muhammad Yunus's Grameen Bank (Bangladesh) pioneered microcredit.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0455","q":"What is the primary regulatory body for microfinance institutions in India?","o":["Securities and Exchange Board of India (SEBI)","National Bank for Agriculture and Rural Development (NABARD)","Reserve Bank of India (RBI)","State Bank of India (SBI)"],"a":2,"x":"The RBI regulates NBFC-MFIs (microfinance institutions); it has set rules on interest rates and household income limits.","e":"NABARD promotes SHG–bank linkage but is not the MFI regulator.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1572","q":"Where is the headquarters of Bandhan Financial Services Limited located?","o":["Surat","Hyderabad","Mumbai","Kolkata"],"a":3,"x":"Bandhan Financial Services and Bandhan Bank are headquartered in Kolkata; Bandhan started as a microfinance NGO in 2001 and became a universal bank in 2015.","e":"IDFC First Bank also got a universal bank licence in 2014-15.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1610","q":"Which type of financial institution serves a specific demographic per their field of membership, such as teachers or members of the military?","o":["Credit Unions","Retail Banks","Commercial banks","Investment Banks and Companies"],"a":0,"x":"Credit unions are member-owned financial cooperatives whose members share a common bond, such as the same profession (teachers) or organisation (military).","e":"In India, cooperative credit societies play a similar role.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q0485","q":"Which among the following is defined as the minimum interest rate of a bank below which it cannot lend, except in some cases allowed by the RBI?","o":["Base rate","Repo rate","Reverse repo rate","Call money rate"],"a":0,"x":"The base rate was the minimum rate below which banks could not lend, except in cases allowed by the RBI; it began in July 2010.","e":"From April 2016 the MCLR replaced it for new loans.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0486","q":"Which among the following banks sponsored the first regional rural bank in India by name Prathama Bank?","o":["Punjab National Bank","Syndicate Bank","Bank of India","State Bank of India"],"a":1,"x":"Prathama Bank, India's first Regional Rural Bank (Moradabad, 2 October 1975), was sponsored by Syndicate Bank.","e":"Syndicate Bank merged into Canara Bank in 2020.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0487","q":"Which among the following is not a method adopted by RBI to maintain the liquidity of economy?","o":["Buying of government bonds","Maintaining cash reserve ratio","Buying of shares","Decreasing repo rate"],"a":2,"x":"The RBI manages liquidity with CRR, repo and reverse repo rates and open market operations (buying and selling government securities). Buying company shares is not one of its tools.","e":"Buying bonds injects liquidity; selling bonds absorbs it.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0488","q":"Which among the following banks is authorised for providing credit for the development of agriculture?","o":["NABARD","RBI","SBI","SIDBI"],"a":0,"x":"NABARD (1982) is the apex bank for agricultural and rural credit, refinancing banks that lend to agriculture.","e":"SIDBI (1990) serves small industries.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0525","q":"Which among the following banks is not a public sector bank?","o":["United Bank of India","Central Bank of India","Lakshmi Vilas Bank","Syndicate Bank"],"a":2,"x":"Lakshmi Vilas Bank was a private-sector bank; it was merged into DBS Bank India in November 2020.","e":"United Bank of India and Syndicate Bank were public sector banks, merged into PNB and Canara Bank in April 2020.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0527","q":"When was the Small Industries Development Bank of India established?","o":["1995","1984","1998","1990"],"a":3,"x":"The Small Industries Development Bank of India was set up on 2 April 1990, under an Act of Parliament, as the apex bank for MSMEs; it is headquartered in Lucknow.","e":"Other apex banks: EXIM Bank (1982), NABARD (1982), NHB (1988).","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0566","q":"Apart from the Oriental bank of Commerce, which of the following banks were merged with Punjab National Bank in April 2020?","o":["Corporation Bank","Andhra Bank","United Bank of India","Canara Bank"],"a":2,"x":"From 1 April 2020, Oriental Bank of Commerce and United Bank of India were merged into Punjab National Bank.","e":"Same day: Syndicate → Canara Bank; Allahabad → Indian Bank; Andhra and Corporation → Union Bank of India.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0606","q":"Which among the following banks was not nationalised in 1969?","o":["Allahabad Bank","Central Bank of India","Bank of India","Andhra Bank"],"a":3,"x":"Andhra Bank was not among the 14 banks nationalised in July 1969; it was nationalised in the second round in April 1980.","e":"1969 nationalisation was under Indira Gandhi (banks with deposits over ₹50 crore).","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0608","q":"Which among the following banks was earlier known as the 'Imperial Bank of India'?","o":["State Bank of India","Bank of India","Reserve Bank of India","Central Bank of India"],"a":0,"x":"The State Bank of India was formerly the Imperial Bank of India (1921), which was nationalised as SBI on 1 July 1955 on the Gorwala Committee's advice.","e":"The Imperial Bank was formed by merging the Presidency Banks of Bengal, Bombay and Madras.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0645","q":"Which among the following institutions acts as the ‘lender of the last resort' in India?","o":["Reserve Bank of India","State Bank of India","National Bank for Agriculture and Rural Development","Central Bank of India"],"a":0,"x":"The RBI is the lender of last resort: it lends to banks in a crisis when no one else will, protecting depositors and the system.","e":"Other RBI roles: banker to the government, banker's bank, custodian of foreign exchange.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0649","q":"Which among the following is the rate at which short term funds are borrowed and lent in the money market?","o":["Bank rate","Repo rate","Reverse Repo rate","Call money rate"],"a":3,"x":"The call money rate is the interest rate on very short-term (overnight) borrowing and lending between banks in the money market.","e":"'Notice money' is for 2 to 14 days; 'term money' for longer.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0685","q":"Which of the following banks primarily focuses on the development of MSME (Micro, Small and Medium Enterprise) sector?","o":["State Bank of India","Small Industries Development Bank of India","National Bank For Agriculture & Rural Development","Reserve Bank of India"],"a":1,"x":"SIDBI (1990, headquartered in Lucknow) is the principal development bank for MSMEs.","e":"NABARD serves agriculture and rural development; EXIM Bank serves exporters.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0687","q":"When was Export-Import Bank of India established?","o":["1975","1970","1996","1982"],"a":3,"x":"The Export-Import (EXIM) Bank of India was set up on 1 January 1982 to finance and promote India's international trade; its headquarters is Mumbai.","e":"NABARD was also set up in 1982.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0727","q":"Amongst the following, the market value of share is described by ___________.","o":["IPO value of the share","buying or selling value of share","book value of share","future values of all earnings on the share"],"a":1,"x":"A share's market value is the price at which it is currently bought and sold on the stock exchange; it changes with demand and supply.","e":"Face value is fixed at issue (for example ₹10); book value is net assets per share.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1296","q":"Which of the following committee's recommendations led to the formation of NABARD?","o":["Shri Homi Sethna Committee","Shri Naresh Chandra Committee","Shri Dharma Vira Committee","Shri B. Sivaraman Committee"],"a":3,"x":"NABARD was set up in 1982 on the advice of the CRAFICARD committee headed by B. Sivaraman.","e":"The Narasimham Committee recommended the RRBs (1975).","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1343","q":"Which among the following banks was inaugurated by Mahatma Gandhi in 1919?","o":["Union Bank of India","State Bank of India","Central Bank of India","Punjab National Bank"],"a":0,"x":"Union Bank of India, founded in Bombay in 1919, was inaugurated by Mahatma Gandhi.","e":"It was nationalised in 1969.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1213","q":"Equity capital and reinvested earnings are part of which component of the capital account?","o":["Direct investment","External assistance","External borrowing","Portfolio investment"],"a":0,"x":"Foreign direct investment in the capital account includes equity capital, reinvested earnings and other capital. Portfolio investment is share and bond buying without a controlling stake.","e":"FDI usually means a lasting interest, commonly 10% or more of equity.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1372","q":"In which year did the Deposit Insurance Corporation start functioning?","o":["1962","1963","1965","1964"],"a":0,"x":"The Deposit Insurance Corporation began work on 1 January 1962; it merged with the Credit Guarantee Corporation in 1978 to form the DICGC.","e":"Deposits are now insured up to ₹5 lakh per depositor per bank (since 2020).","src":["TGT 24 Jun 2023 S2"]},{"id":"q1383","q":"As per RBI guidelines for licensing small finance banks in the private sector, the promoter's minimum initial share in paid-up equity capital shall be at least ______.","o":["45 per cent","50 per cent","60 per cent","40 per cent"],"a":3,"x":"Under the RBI's small finance bank licensing guidelines, promoters must initially hold at least 40% of paid-up equity capital, reduced over time.","e":"Small finance banks must lend 75% of net credit to priority sectors.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1406","q":"Which of the following terms is used for the rate at which commercial banks borrow money by selling their securities to the Reserve Bank of India?","o":["Repo rate","Reverse bank rate","Bank rate","Reverse repo rate"],"a":0,"x":"The repo rate is the rate at which the RBI lends to commercial banks against securities; banks sell securities to the RBI with an agreement to buy them back.","e":"Reverse repo is the rate at which the RBI borrows from banks.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1483","q":"In which year was ICICI formed at the initiative of the World Bank, the Government of India and representatives of Indian industry?","o":["1982","1975","1955","1966"],"a":2,"x":"ICICI (Industrial Credit and Investment Corporation of India) was formed in 1955 at the initiative of the World Bank, the Government of India and Indian industry.","e":"ICICI Bank came later (1994); the two merged in 2002.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1502","q":"What is the difference between the interest rate paid by banks to depositors and the interest rate charged from borrowers called?","o":["Profit margin","Spread","Cash reserve","Liquidity ratio"],"a":1,"x":"The spread (net interest margin) is the gap between the interest banks charge borrowers and the interest they pay depositors.","e":"Lending rate 10% − deposit rate 6% = 4% spread.","src":["TGT 29 Aug 2025"]},{"id":"q1527","q":"In microfinance in India, what is the significance of the 'Joint Liability Group (JLG)' model?","o":["It ensures compliance with environmental sustainability standards.","It provides government subsidies to support agricultural investment.","It enables group-based lending to reduce credit risk and increase repayment rates.","It allows MFIs to diversify their loan portfolios across sectors."],"a":2,"x":"In the Joint Liability Group model, 4–10 borrowers guarantee each other's loans. The group pressure cuts credit risk and raises repayment rates without collateral.","e":"NABARD has promoted JLGs for tenant farmers since 2006.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1544","q":"Which of the following is NOT a function of money in an economy?","o":["Unit of labour","Medium of exchange","Standard of deferred payment","Store of value"],"a":0,"x":"Money works as a medium of exchange, a unit of account (not a 'unit of labour'), a store of value and a standard of deferred payment.","e":"Barter fails without a 'double coincidence of wants', which money solves.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0798","q":"Which of the following organisations are involved in the bi-lateral cooperation programme, 'Rural Financial Institutions Programme' (RFIP), to facilitate effective financial inclusion of low-income households in India?","o":["NABARD and Cooperative for Assistance and Relief Everywhere","RBI and United Nations Development Programme","SIDBI and World Bank","NABARD and German Society for International Cooperation"],"a":3,"x":"The Rural Financial Institutions Programme (RFIP) was a bilateral Indo-German programme between NABARD and GIZ (German Society for International Cooperation) to widen financial inclusion.","e":"GIZ is Germany's development cooperation agency.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0846","q":"Which institution is primarily responsible for providing and regulating credit for the promotion of agriculture and rural development in India?","o":["Securities and Exchange Board of India (SEBI)","State Level Bankers Committee (SLBC)","State Bank of India (SBI)","National Bank for Agriculture and Rural Development (NABARD)"],"a":3,"x":"NABARD (1982) is the apex institution for credit for agriculture and rural development.","e":"It refinances cooperative banks and RRBs.","src":["PGT 14 Jul 2025"]}]},{"id":"planning","n":"Planning, Budget and Reforms","qs":[{"id":"q0015","q":"What was the main focus of the First Five-Year Plan?","o":["Agriculture","Nuclear power","Heavy industries","Tourism"],"a":0,"x":"The First Five-Year Plan (1951–56), built on the Harrod–Domar model, gave top priority to agriculture and irrigation after the food shortages of Partition.","e":"The Second Plan (1956–61, Mahalanobis model) switched the focus to heavy industry.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0053","q":"What was a key technological advancement of the Green Revolution?","o":["The development of organic fertilisers","The reduction in the use of chemical pesticides","The introduction of high-yielding variety (HYV) seeds","The decrease in irrigation practices"],"a":2,"x":"The Green Revolution of the mid-1960s was driven by high-yielding variety (HYV) seeds, especially wheat and rice, used with fertilisers, pesticides and assured irrigation.","e":"M. S. Swaminathan is called the father of India's Green Revolution; Norman Borlaug developed the Mexican dwarf wheat.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0129","q":"The policy of import substitution promotes ______.","o":["the use of only those goods which are produced within the country","the use of only imported goods for public sector activities","the export of those goods which other countries prefer to import","the production of goods which are generally imported"],"a":3,"x":"Import substitution means producing at home the goods the country used to import, usually behind tariffs, to save foreign exchange and build industry.","e":"India followed it from the Second Plan until the 1991 reforms.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0208","q":"Which of the following is NOT an effect of the Green Revolution?","o":["Attaining marketable surplus","Benefit to low income groups","Decrease in agricultural productivity","Buffer stock of food grains"],"a":2,"x":"The Green Revolution raised agricultural productivity, created marketable surpluses and built food buffer stocks. A fall in productivity was not an effect.","e":"Its downsides were regional inequality and soil and water damage.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0267","q":"Which body was established as an extra-constitutional advisory agency to support the union in policy planning?","o":["Supreme Court of India","Election Commission","Planning Commission (now NITI Aayog)","Finance Commission"],"a":2,"x":"The Planning Commission (1950) was extra-constitutional and non-statutory, set up by a Cabinet resolution. NITI Aayog replaced it on 1 January 2015.","e":"The Finance Commission is constitutional (Article 280).","src":["ASO 20 Aug 2025 S2"]},{"id":"q0290","q":"Which of the following was a common goal of India's various Five-Year Plans?","o":["Expansion of the service sector","Self-reliance","Dependence on imports","Decrease in agricultural production"],"a":1,"x":"Self-reliance was a common goal of India's Five-Year Plans, along with growth, modernisation and equity.","e":"The Fourth Plan (1969–74) stressed 'growth with stability and progressive achievement of self-reliance'.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0407","q":"Which major policy, implemented in 2011, aims to increase the growth of the industrial sector in India?","o":["National Agricultural Policy","Industrial Licensing Policy","Special Economic Zones Act","National Manufacturing Policy"],"a":3,"x":"The National Manufacturing Policy (2011) aimed to raise manufacturing to 25% of GDP and create 100 million jobs, including through National Investment and Manufacturing Zones.","e":"Make in India (2014) continued the same goals.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0459","q":"The first phase of the Green Revolution in India was primarily focussed on _________________.","o":["green vegetable production","oil seed production","wheat production","pulses production"],"a":2,"x":"The first phase of the Green Revolution (1960s) focused mainly on wheat, in Punjab, Haryana and western Uttar Pradesh.","e":"Rice got the benefits later; pulses and oilseeds lagged.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1607","q":"When was the Economic Survey decoupled from the Indian Union Budget?","o":["1964","1954","1951","1960"],"a":0,"x":"The Economic Survey was first presented in 1950-51 as part of the Union Budget and was separated from the Budget documents in 1964.","e":"It is prepared by the Chief Economic Adviser and presented a day before the Budget.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q0489","q":"Which among the following is not a component of fiscal policies adopted by the Government?","o":["Cash reserve ratio","Government spending","Taxes","Subsidies"],"a":0,"x":"Fiscal policy is the government's use of spending, taxes and subsidies. CRR is a monetary policy tool of the RBI.","e":"Monetary policy: repo rate, CRR, SLR, open market operations.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0605","q":"A _____________ was originally defined as a tax on all spot conversions of one currency into another.","o":["Tobin tax","Pigouvian tax","Octroi tax","Corporate tax"],"a":0,"x":"The Tobin tax, proposed by James Tobin (1972), was a tax on all spot conversions of one currency into another, meant to curb currency speculation.","e":"A Pigouvian tax targets negative externalities, such as a carbon tax.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0607","q":"The Union Budget was presented at 5 pm in the Parliament till the year __________.","o":["1995","2001","2000","2005"],"a":2,"x":"The Union Budget was presented at 5 pm until 2000; from 2001, Yashwant Sinha shifted it to 11 am.","e":"Since 2017 it has been presented on 1 February.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0609","q":"Who among the following was the first woman to have presented the budget in the parliament?","o":["Sonia Gandhi","Pratibha Patil","Indira Gandhi","Nirmala Sitharaman"],"a":2,"x":"Indira Gandhi was the first woman to present the Union Budget (1970), as Prime Minister holding Finance.","e":"Nirmala Sitharaman is the first full-time woman Finance Minister (2019).","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0646","q":"After India became independent in 1947, the country's first Finance Minister, __________ presented the first budget.","o":["Yashwant Sinha","Manmohan Singh","Morarji Desai","Shanmukham Chetty"],"a":3,"x":"R. K. Shanmukham Chetty, independent India's first Finance Minister, presented its first budget on 26 November 1947.","e":"The first budget of the Republic (1950) was presented by John Mathai.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0648","q":"Which among the following is an example of indirect tax?","o":["Income tax","Sales tax","Gift tax","Expenditure tax"],"a":1,"x":"Sales tax is an indirect tax: it is paid by the consumer but collected and deposited by the seller. Income, gift and expenditure taxes are direct.","e":"GST (2017) replaced most indirect taxes, including state sales tax (VAT).","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0686","q":"Who among the following holds the record of presenting the most number of financial budgets as of April 2020?","o":["Yashwant Sinha","Nirmala Sitharaman","Morarji Desai","Pranab Mukherjee"],"a":2,"x":"Morarji Desai presented the most Union Budgets: ten in all, including two interim budgets.","e":"Nirmala Sitharaman presented her 8th consecutive budget in 2025.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0688","q":"Which among the following taxes is imposed on the bodies that have negative externality?","o":["Pigouvian tax","Tobin tax","Octroi tax","Smith tax"],"a":0,"x":"A Pigouvian tax (after Arthur Pigou) is levied on activities with negative externalities, so polluters pay for the harm they cause.","e":"A carbon tax is a Pigouvian tax.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0725","q":"Amongst the following, who presents the Union Budget of India in Parliament?","o":["Chief Economic Advisor","Finance Secretary","Finance Minister","Prime Minister"],"a":2,"x":"The Union Finance Minister presents the Union Budget (Annual Financial Statement, Article 112) in Parliament.","e":"The first Union Budget of independent India was presented in 1947.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q0726","q":"Amongst the following, who became the first Chairman of the Planning Commission in 1950?","o":["Sardar Vallabhbhai Patel","Jawaharlal Nehru","Indira Gandhi","Morarji Desai"],"a":1,"x":"Jawaharlal Nehru, as Prime Minister, was the first chairman of the Planning Commission (15 March 1950); Gulzarilal Nanda was the first deputy chairman.","e":"The Prime Minister also chairs NITI Aayog.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q0754","q":"In India, as of April 2020, which one of the following taxes is levied at both the central and the state level?","o":["Excise duty","Goods and Service Tax","Basic customs duty","Octroi"],"a":1,"x":"GST is levied by both the Centre (CGST) and the states (SGST) on intra-state supplies; IGST covers inter-state supplies.","e":"The 101st Amendment (2016) made the dual GST possible.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1302","q":"What was the duration of the Second Five Year Plan?","o":["1957-62","1958-63","1955-60","1956-61"],"a":3,"x":"The Second Five-Year Plan ran from 1956 to 1961, stressing industrialisation on the Mahalanobis model.","e":"First Plan: 1951–56. Third Plan: 1961–66.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1333","q":"The Goods and Services Tax was introduced in ________ in India.","o":["2017","2018","2019","2016"],"a":0,"x":"GST was introduced in India on 1 July 2017, replacing many central and state indirect taxes.","e":"GST Day is observed on 1 July.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q0899","q":"Which of the following is NOT a benefit of the LPG reforms?","o":["Increased foreign investment","Access to modern technology","Reduction in competition","Growth in GDP"],"a":2,"x":"The 1991 LPG (liberalisation, privatisation, globalisation) reforms brought more foreign investment, access to modern technology and faster GDP growth. They increased competition, not reduced it.","e":"The reforms were led by PM P. V. Narasimha Rao and Finance Minister Manmohan Singh.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0937","q":"Outsourcing is one of the important outcomes of which process?","o":["Communism","Liberalisation","Globalisation","Capitalisation"],"a":2,"x":"Outsourcing — firms hiring outside agencies, often abroad, for services such as call centres and IT — is a key result of globalisation and cheap communication.","e":"India became a BPO hub after the 1990s.","src":["PRT 18 Feb 2026 S1"]},{"id":"q1000","q":"Which of the following was a major goal of India's 1991 trade and investment policy reforms?","o":["Promote local handicrafts","Increase population growth","Enhance international competitiveness and attract foreign investments","Eliminate all taxes"],"a":2,"x":"The 1991 trade and investment reforms aimed to make Indian industry internationally competitive and attract foreign investment by cutting tariffs and licensing.","e":"FDI up to 51% was allowed automatically in priority industries in 1991.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1043","q":"What was the maximum investment limit for the classification of small-scale industrial units in India in 1950?","o":["Rupees fifty lakh","Rupees ten lakh","Rupees one crore","Rupees five lakh"],"a":3,"x":"In 1950 a small-scale industrial unit was one with investment up to ₹5 lakh in fixed assets; the limit has been raised many times.","e":"Since 2020 MSMEs are classified by both investment and turnover.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1098","q":"Since 1991, how have trade policy reforms aimed to affect the competitiveness of Indian goods in international markets?","o":["By increasing government control over trade","By raising tariffs and quantitative restrictions","By lowering tariffs and removing quantitative restrictions","By reducing foreign investment"],"a":2,"x":"Trade reforms since 1991 cut tariffs and removed quantitative restrictions such as import quotas and licences, making Indian goods more competitive abroad.","e":"The rupee was also devalued in July 1991.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1147","q":"Which economic reform in India aimed at liberalising the industrial sector and reducing government control?","o":["Industrial Policy, 1948","New Economic Policy, 1991","Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA)","Demonetisation"],"a":1,"x":"The New Economic Policy of 1991 liberalised industry: it ended most industrial licensing, cut reserved public-sector areas and opened the economy to foreign investment.","e":"MGNREGA is a rural jobs law; demonetisation (2016) was a currency measure.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1178","q":"Why was NITI Aayog established as a replacement for the Planning Commission?","o":["To limit state participation in national policies","To abolish financial allocation mechanisms","To centralise policymaking in the Union Government","To strengthen cooperative federalism in policy formulation"],"a":3,"x":"NITI Aayog (1 January 2015) replaced the Planning Commission to encourage cooperative federalism: states help shape policy instead of receiving top-down plans.","e":"The Prime Minister is its chairperson; all Chief Ministers sit on its Governing Council.","src":["PRT 31 Mar 2026 S1"]},{"id":"q1212","q":"The 'Make in India' initiative was launched mainly in response to which national concern?","o":["A sharp decline in economic growth and the need to revive growth through manufacturing and innovation","A steep rise in foreign debt and the need to promote agricultural exports","Pressure from international organisations to liberalise the economy and privatise public enterprises","A widening trade deficit and rising inflation after the 2008 global financial crisis"],"a":0,"x":"'Make in India' (September 2014) answered slowing growth and a weak manufacturing share by pushing investment, innovation and domestic manufacturing.","e":"Its symbol is a lion made of gears.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1256","q":"The second Five Year Plan in India was formulated on whose ideas?","o":["T.T. Krishnamachari","Prasanta Chandra Mahalanobis","Dr. John Mathai","R.K. Shanmukham Chetty"],"a":1,"x":"The Second Five-Year Plan (1956–61) was based on P. C. Mahalanobis's model, which stressed heavy industry and the public sector.","e":"Mahalanobis founded the Indian Statistical Institute (1931); his birthday, 29 June, is Statistics Day.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1433","q":"Receipts which neither create any liability nor reduce the assets of the government are called ______.","o":["self-assessed receipts","revenue receipts","capital receipts","standard receipts"],"a":1,"x":"Revenue receipts neither create a liability nor reduce the government's assets: taxes, fees, dividends. Capital receipts do (borrowing, disinvestment).","e":"Borrowing creates a liability, so it is a capital receipt.","src":["TGT 25 Jun 2023 S2"]},{"id":"q0762","q":"According to the Industrial Policy Resolution of 1948, which industrial policy model did India adopt?","o":["A mixed economy model with important roles for both the public and private sectors","A purely capitalist model driven by private enterprise","A fully socialist economy with complete state ownership of industries","A laissez-faire model with minimum government intervention in industry"],"a":0,"x":"The Industrial Policy Resolution of 1948 set up a mixed economy, with important roles for both the public and private sectors.","e":"The 1956 Resolution then gave the public sector the leading role.","src":["PGT 25 Sep 2025"]},{"id":"q0780","q":"Why is the Industrial Policy Resolution (IPR) of 1956 often called the 'economic constitution of India'?","o":["Because it began the liberalisation and privatisation of major industries.","Because it introduced a socialist economy and banned foreign investment.","Because it ended private ownership in all major industries.","Because it classified industries into categories and laid the foundation of public-sector-led growth."],"a":3,"x":"The Industrial Policy Resolution of 1956 is called India's 'economic constitution' because it sorted industries into three schedules and made the public sector the base of growth.","e":"Schedule A: exclusive state monopoly (17 industries); B: state-led with private participation; C: private sector.","src":["PGT 25 Sep 2025"]},{"id":"q0827","q":"____________________ means fixing the maximum size of land which could be owned by an individual, with the purpose of reducing the concentration of land ownership in a few hands.","o":["Land ceiling","Unification of land","Land redistribution","Land consolidation"],"a":0,"x":"Land ceiling fixes the maximum land an individual or family may own, so the surplus can go to the landless and ownership is not concentrated.","e":"Land ceiling was a major land reform after Independence, along with zamindari abolition.","src":["PGT 26 Sep 2025"]},{"id":"q0873","q":"The Income Tax Appellate Tribunal (ITAT) handles appeals relating to which category of tax?","o":["Central Goods and Services Tax","Goods and Services Tax","Value Added Tax","Corporate tax"],"a":3,"x":"The Income Tax Appellate Tribunal (1941) hears appeals on direct taxes such as income tax and corporate tax. GST disputes go to the GST Appellate Tribunal.","e":"ITAT was the first tribunal set up in India.","src":["PGT 24 Sep 2025"]}]},{"id":"schemes","n":"Government Schemes and Policies","qs":[{"id":"q0043","q":"What is the ratio of the expenditure for the National Food for Work Programme shared between the Central and State Governments in India?","o":["90 : 10","100 : 0","75 : 25","50 : 50"],"a":1,"x":"The National Food for Work Programme (November 2004, in 150 backward districts) was 100% centrally sponsored. It was merged into MGNREGA in 2006.","e":"MGNREGA's funding is different: the Centre pays all unskilled wages and 75% of material costs.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0172","q":"The Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA) guarantees how many days of wage employment in a year?","o":["100 days","50 days","200 days","150 days"],"a":0,"x":"MGNREGA (2005) guarantees 100 days of wage employment a year to every rural household whose adults volunteer for unskilled manual work.","e":"If work is not given within 15 days of applying, an unemployment allowance is due.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0227","q":"National Literacy Mission was launched in which of the following years by the Government of India?","o":["1988","1989","1990","1987"],"a":0,"x":"The National Literacy Mission was launched on 5 May 1988 to make adults aged 15–35 functionally literate.","e":"It was followed by Saakshar Bharat (2009).","src":["ASO 20 Aug 2025 S1"]},{"id":"q0240","q":"With reference to the education policies in India, identify whether the following statements are correct or incorrect. A: The National Policy on Education was adopted in the year 1986. B: The National Education Policy (NEP) was adopted in the year 2020.","o":["Both A and B are correct.","A is incorrect and B is correct.","A is correct and B is incorrect.","Both A and B are incorrect."],"a":0,"x":"Both are correct: the National Policy on Education was adopted in 1986 (modified 1992), and the National Education Policy in 2020.","e":"NEP 2020 brings the 5+3+3+4 school structure.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0253","q":"Which government initiative focuses on self-employment opportunities in rural India?","o":["Deen Dayal Antyodaya Yojana – National Rural Livelihoods Mission (DAY-NRLM)","National Rural Livelihood Promotion Society (NRLPS)","Sagarmala Project","Mahatama Gandhi Gramin Basti Yojana Scheme (MGGBYS)"],"a":0,"x":"DAY-NRLM (Aajeevika, 2011) builds self-employment for rural poor households, mainly through women's Self-Help Groups.","e":"The urban version is DAY-NULM.","src":["ASO 20 Aug 2025 S2"]},{"id":"q1593","q":"Which of the following programs was launched by the Govt. of India to provide connectivity to unconnected habitations as part of a poverty reduction strategy?","o":["Pradhan Mantri Gram Sadak Yojana","Pradhan Mantri Gram Connectivity Scheme","PM Rural Road Transport Network Program","PM Gram Setu Yojana"],"a":0,"x":"Pradhan Mantri Gram Sadak Yojana (25 December 2000) gives all-weather road links to unconnected rural habitations as part of poverty reduction.","e":"It is run by the Ministry of Rural Development.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q0573","q":"The Swachh Bharat Abhiyan (Urban) lies under the ______________.","o":["Ministry of Drinking Water and Sanitation","Ministry of External Affairs","Ministry of Housing and Urban Affairs","Ministry of Home Affairs"],"a":2,"x":"Swachh Bharat Mission (Urban) is run by the Ministry of Housing and Urban Affairs; SBM (Grameen) by the Jal Shakti Ministry's Department of Drinking Water and Sanitation.","e":"Swachh Bharat was launched on 2 October 2014.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q1270","q":"Which of the following schemes of the Government of India provides pensions to poor elderly individuals who lack support from caregivers?","o":["National Social Assistance Programme","Mahatma Gandhi National Rural Employment Guarantee Act","National Rural Employment Guarantee Scheme","Pradhan Mantri Awas Yojana"],"a":0,"x":"The National Social Assistance Programme (15 August 1995) gives pensions to poor elderly people, widows and persons with disabilities, including the Indira Gandhi National Old Age Pension Scheme.","e":"It is run by the Ministry of Rural Development.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1272","q":"The 'Prime Minister's Employment Generation Programme (PMEGP)' is administered by which of the following Ministries of the Government of India?","o":["Ministry of Micro, Small and Medium Enterprises","Ministry of Rural Development","Ministry of Labour and Employment","Ministry of Home Affairs"],"a":0,"x":"The Prime Minister's Employment Generation Programme (2008) is run by the Ministry of MSME through KVIC; it gives credit-linked subsidies to set up small enterprises.","e":"It merged the PMRY and REGP schemes.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1526","q":"Which non-farm employment is associated with Operation Flood?","o":["Fisheries","Information technology","Horticulture","Animal husbandry"],"a":3,"x":"Operation Flood (1970, NDDB, led by Dr Verghese Kurien) was the White Revolution in dairying, a form of animal husbandry, which made India the world's largest milk producer.","e":"National Milk Day is 26 November, Kurien's birthday.","src":["TGT 24 Aug 2025 S3"]}]}]});
